async function runPostLoginMigrations(user){await syncT9TemplatesOnce(user);await reconcileT9RosterOnce(user);await normalizeStoredHoursOnce(user)}
async function normalizeStoredHoursOnce(user){const key=`happychild:whole-hour-v1:${user.uid}`;if(localStorage.getItem(key)==="done")return;try{const result=await normalizeAllScheduleHours(user);localStorage.setItem(key,"done");const changed=result.templates+result.sessions;if(changed)toast(`Đã làm tròn xuống ${changed} lịch về giờ tròn.`)}catch(error){console.error("Không thể chuẩn hóa giờ học",error)}}
