function startSubscriptions(){
  state.autoCompleteTimer=setInterval(maybeAutoCompleteElapsedSessions,60000);
  state.unsubs.push(subscribe("students",(v,e)=>{state.ready.students=!e;if(e)toast("Không thể tải học sinh: "+e.message,"error");else state.students=v;render();maybeShowDailyBrief()}));
  state.unsubs.push(subscribe("teachers",(v,e)=>{state.ready.teachers=!e;if(e)toast("Không thể tải giáo viên: "+e.message,"error");else state.teachers=v;render();maybeShowDailyBrief()}));
  state.unsubs.push(subscribeStudentForms((v,e)=>{state.ready.studentForms=!e;if(e)toast("Không thể tải Link Form: "+e.message,"error");else state.studentForms=v;render();maybeShowDailyBrief()}));
  state.unsubs.push(subscribe("scheduleTemplates",(v,e)=>{if(e)return toast("Không thể tải lịch mẫu: "+e.message,"error");state.templates=v;render()}));
  state.unsubs.push(subscribe("weeks",(v,e)=>{if(e)return toast("Không thể tải danh sách tuần: "+e.message,"error");state.weeks=v.sort((a,b)=>(a.startDate?.seconds||0)-(b.startDate?.seconds||0));if(!state.weekId&&v.length)selectWeek((todayWeek()||v.at(-1)).id);else render()}));
  state.unsubs.push(subscribeNotes((v,e)=>{state.ready.notes=true;if(e)toast("Không thể tải ghi chú: "+e.message,"error");else state.notes=v;render();maybeShowDailyBrief()}));
  state.unsubs.push(subscribeRecentAudit((v,e)=>{if(e)return;state.audits=v;render()}));state.unsubs.push(subscribeTransactions((v,e)=>{if(e)return;state.transactions=v;render()}));
}
function selectWeek(id){const requestId=++state.sessionRequestId;state.weekId=id;state.sessions=[];state.sessionsReady=false;state.sessionsWeekId=null;state.sessionsLoadingWeekId=id;state.sessionsError="";state.autoCompleteRetryAt=0;state.sessionUnsub?.();state.sessionUnsub=null;render();state.sessionUnsub=subscribeSessions(id,(v,e)=>{if(requestId!==state.sessionRequestId||state.weekId!==id)return;state.sessionsLoadingWeekId=null;if(e){state.sessionsReady=false;state.sessionsError=e.message||"Không thể tải lịch tuần.";toast("Không thể tải lịch tuần: "+state.sessionsError,"error");render();return}state.sessions=Array.isArray(v)?v:[];state.sessionsWeekId=id;state.sessionsReady=true;state.sessionsError="";render();maybeAutoCompleteElapsedSessions()});}
async function maybeAutoCompleteElapsedSessions(){if(state.autoCompleting||!state.user||!state.sessionsReady||state.sessionsWeekId!==state.weekId||!navigator.onLine||Date.now()<state.autoCompleteRetryAt)return;const weekId=state.weekId,snapshot=state.sessions.slice();state.autoCompleting=true;try{const result=await autoCompleteElapsedSessions(weekId,snapshot,state.user,new Date());if(state.weekId!==weekId)return;if(result.updated)toast(`Đã tự cập nhật ${result.updated} buổi học đã qua giờ.`);if(result.failed?.length){state.autoCompleteRetryAt=Date.now()+60000;toast(`${result.failed.length} buổi chưa thể tự cập nhật. Hệ thống sẽ thử lại sau.`,"error")}}catch(error){state.autoCompleteRetryAt=Date.now()+60000;console.error(error)}finally{state.autoCompleting=false}}

window.addEventListener("hashchange",route);function route(){const view=location.hash.slice(1)||"dashboard";$("#viewTitle").textContent=titles[view]||titles.dashboard;document.querySelectorAll("#mainNav a").forEach(a=>a.classList.toggle("active",a.dataset.view===view));$(".sidebar").classList.remove("open");const current=todayWeek();if(view==="dashboard"&&current&&current.id!==state.weekId)return selectWeek(current.id);render(view)}
function currentView(){return location.hash.slice(1)||"dashboard"}function render(view=currentView()){if(!state.user)return;const fn={dashboard:renderDashboard,month:renderMonthOverview,calendar:renderCalendarV2,students:renderStudents,teachers:renderTeachers,forms:renderStudentForms,templates:renderTemplates,makeup:renderMakeupV2,reports:renderReportsV2,notes:renderNotes,history:renderHistory,settings:renderSettings}[view]||renderDashboard;fn();if(view==="students")enhanceStudentRows()}
const empty=(title,text)=>`<div class="empty"><strong>${title}</strong>${text}</div>`;
const weekOptions=()=>state.weeks.map(w=>`<option value="${escapeHtml(w.id)}" ${w.id===state.weekId?"selected":""}>${escapeHtml(w.label)}</option>`).join("");
const safeColor=(value,fallback="#7c5ce7")=>/^#[0-9a-f]{6}$/i.test(String(value||""))?String(value):fallback;
const normalizeWholeHourRange=data=>{data.startTime=floorScheduleTime(data.startTime);data.endTime=floorScheduleTime(data.endTime);if(!data.startTime||!data.endTime||data.startTime>=data.endTime)throw new Error("Sau khi làm tròn xuống, giờ kết thúc phải sau giờ bắt đầu.");return data};
const TIME_PATTERN=/^(?:[01]\d|2[0-3]):[0-5]\d$/;
const safeTime=(value,fallback="—")=>TIME_PATTERN.test(String(value||""))?String(value):fallback;
const safeCapacity=value=>{const number=Number(value);return Number.isInteger(number)&&number>=1&&number<=20?number:1};
const safeDay=value=>{const number=Number(value);return Number.isInteger(number)&&number>=0&&number<=6?number:null};
const safeSessionType=value=>value==="makeup"?"makeup":"regular";
const safeSessionStatus=(value,type=safeSessionType())=>{const allowed=type==="makeup"?["makeup_scheduled","makeup_completed","cancelled"]:["scheduled","attended","absent","cancelled"];return allowed.includes(value)?value:(type==="makeup"?"makeup_scheduled":"scheduled")};
const sessionUi=session=>{const type=safeSessionType(session?.type),storedStatus=safeSessionStatus(session?.status,type),status=elapsedSessionTarget({...session,type,status:storedStatus},new Date())||storedStatus;return {type,status,startTime:safeTime(session?.startTime),endTime:safeTime(session?.endTime),capacity:safeCapacity(session?.capacity)}};
const displayIsoDate=value=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(value||""))return "—";const [y,m,d]=value.split("-");return `${d}/${m}/${y}`};
const displayPersonBirth=person=>(person.birthday||person.birthDate)?displayIsoDate(person.birthday||person.birthDate):escapeHtml(person.birthYear||"—");
function dailyReminders(date){const dateKey=isoDate(date),monthDay=dateKey.slice(5),items=[];state.students.filter(x=>x.active&&(x.birthday||x.birthDate)?.slice(5)===monthDay).forEach(x=>{const birthday=x.birthday||x.birthDate;items.push({kind:"birthday",title:`Sinh nhật bé ${x.fullName}`,detail:`Ngày sinh ${displayIsoDate(birthday)}`})});state.teachers.filter(x=>x.active&&(x.birthday||x.birthDate)?.slice(5)===monthDay).forEach(x=>{const birthday=x.birthday||x.birthDate;items.push({kind:"birthday",title:`Sinh nhật ${x.fullName}`,detail:`Ngày sinh ${displayIsoDate(birthday)}`})});state.notes.filter(x=>x.dateKey===dateKey).forEach(x=>items.push({kind:"note",title:x.title||"Ghi chú",detail:x.details||""}));return items}
