function maybeShowDailyBrief(){const remindersReady=state.ready.students&&state.ready.teachers&&state.ready.notes;if(state.briefShown||!state.user||!remindersReady)return;if($("#formDialog")?.open)return setTimeout(maybeShowDailyBrief,250);state.briefShown=true;const today=new Date(),tomorrow=addDays(today,1),dlg=$("#briefingDialog");$("#briefingBody").innerHTML=`<div class="briefing-grid"><section class="brief-day"><header><span class="badge purple">HÔM NAY</span><h3>${localDate(today)}</h3></header>${reminderList(today)}</section><section class="brief-day"><header><span class="badge success">NGÀY MAI</span><h3>${localDate(tomorrow)}</h3></header>${reminderList(tomorrow)}</section></div>`;const close=()=>dlg.close();$("#briefingClose").onclick=close;$("#briefingDone").onclick=close;try{dlg.showModal()}catch{dlg.setAttribute("open","")}}

