function studentLearningStats(sessions){const result={learnedCount:0,learnedMinutes:0,absentCount:0,absentMinutes:0,makeupCount:0,makeupMinutes:0,plannedCount:0,plannedMinutes:0};sessions.forEach(session=>{const ui=sessionUi(session),minutes=sessionMinutes(session);if(ui.status!=="cancelled"){result.plannedCount++;result.plannedMinutes+=minutes}if(ui.type==="regular"&&ui.status==="attended"){result.learnedCount++;result.learnedMinutes+=minutes}else if(ui.type==="regular"&&ui.status==="absent"){result.absentCount++;result.absentMinutes+=minutes}else if(ui.type==="makeup"&&ui.status==="makeup_completed"){result.makeupCount++;result.makeupMinutes+=minutes}});return result}
function profileStatsTable(sessions){const now=new Date(),weekStart=mondayFor(now),weekEnd=isoDate(addDays(new Date(`${weekStart}T12:00:00`),6)),month=currentMonth(),periods=[{label:"Tuần hiện tại",rows:sessions.filter(item=>item.dateKey>=weekStart&&item.dateKey<=weekEnd)},{label:"Tháng hiện tại",rows:sessions.filter(item=>String(item.dateKey||"").startsWith(`${month}-`))},{label:"Tất cả thời gian",rows:sessions}];return `<div class="profile-stats-grid">${periods.map(period=>{const stats=studentLearningStats(period.rows);return `<article class="profile-stat-card"><h3>${period.label}</h3><div><span><small>Đã học</small><strong>${stats.learnedCount} buổi · ${formatHours(stats.learnedMinutes)}</strong></span><span><small>Nghỉ phép</small><strong>${stats.absentCount} buổi · ${formatHours(stats.absentMinutes)}</strong></span><span><small>Đã học bù</small><strong>${stats.makeupCount} buổi · ${formatHours(stats.makeupMinutes)}</strong></span><span><small>Tổng đã xếp</small><strong>${stats.plannedCount} buổi · ${formatHours(stats.plannedMinutes)}</strong></span></div></article>`}).join("")}</div>`}
function profileWeekList(sessions){const groups=new Map();sessions.forEach(session=>{const key=session.weekId||"unknown",group=groups.get(key)||{id:key,label:session.weekLabel||"Tuần không rõ",start:session.weekStartDate,end:session.weekEndDate,rows:[]};group.rows.push(session);groups.set(key,group)});const ordered=[...groups.values()].sort((a,b)=>{const aTime=a.start?.toDate?a.start.toDate().getTime():0,bTime=b.start?.toDate?b.start.toDate().getTime():0;return bTime-aTime}),today=new Date(),current=ordered.find(group=>group.start?.toDate&&group.end?.toDate&&group.start.toDate()<=today&&group.end.toDate()>=today),openId=(current||ordered[0])?.id;return `<div class="profile-week-list">${ordered.map(group=>{const stats=studentLearningStats(group.rows),rows=group.rows.slice().sort((a,b)=>String(a.dateKey||"").localeCompare(String(b.dateKey||""))||String(a.startTime||"").localeCompare(String(b.startTime||""))).map(session=>{const ui=sessionUi(session),tc=teacher(session.teacherId);return `<article class="profile-session-row status-${ui.status}" style="--teacher:${safeColor(tc.color,"#94a3b8")}"><span class="profile-session-date"><strong>${displayIsoDate(session.dateKey)}</strong><small>${ui.startTime}–${ui.endTime}</small></span><span><strong>${escapeHtml(tc.fullName)}</strong><small>${ui.type==="makeup"?"Học bù":"Buổi thường"} · ${escapeHtml(STATUS[ui.status]||ui.status)}</small>${session.note?`<em>${escapeHtml(session.note)}</em>`:""}</span></article>`}).join("");return `<details class="profile-week" ${group.id===openId?"open":""}><summary><span><strong>${escapeHtml(group.label)}</strong><small>${group.rows.length} buổi được xếp</small></span><span class="profile-week-badges"><span class="badge success">${stats.learnedCount} học</span><span class="badge danger">${stats.absentCount} nghỉ</span><span class="badge purple">${stats.makeupCount} bù</span><i aria-hidden="true">⌄</i></span></summary><div class="profile-session-list">${rows}</div></details>`}).join("")||empty("Chưa có lịch sử tuần","Học sinh chưa có buổi học nào trong các tuần đã tạo.")}</div>`}
async function openStudentProfile(studentId){const person=student(studentId),dialog=$("#studentProfileDialog"),body=$("#studentProfileBody"),requestId=++state.studentProfileRequestId;$("#studentProfileTitle").textContent=person.fullName;body.innerHTML=`<div class="notice info">Đang tải lịch học và thống kê của ${escapeHtml(person.fullName)}…</div>`;$("#studentProfileClose").onclick=()=>dialog.close();if(!dialog.open)try{dialog.showModal()}catch{dialog.setAttribute("open","")}try{const sessions=await loadStudentHistory(studentId);if(requestId!==state.studentProfileRequestId||!dialog.open)return;body.innerHTML=`<div class="profile-person-strip" style="--person:${safeColor(person.color,"#94a3b8")}"><i class="color-dot" aria-hidden="true"></i><span><strong>${escapeHtml(person.fullName)}</strong><small>${displayPersonBirth(person)} · Còn ${Number(person.makeupBalance)||0} buổi cần bù</small></span><button id="refreshStudentProfile" class="button ghost small" type="button">Làm mới</button></div>${profileStatsTable(sessions)}<div class="section-head profile-weeks-head"><div><h2>Các tuần đã học</h2><p class="muted">Trạng thái và ghi chú lấy trực tiếp từ lịch tuần.</p></div></div>${profileWeekList(sessions)}`;$("#refreshStudentProfile").onclick=()=>openStudentProfile(studentId)}catch(error){if(requestId!==state.studentProfileRequestId)return;body.innerHTML=`<div class="notice"><strong>Không thể tải hồ sơ học tập.</strong><br>${escapeHtml(error.message||"Lỗi không xác định")}</div>`}}

const calendarStudentMatches=(session,query)=>{if(!query)return true;const person=student(session.studentId),haystack=[person.fullName,person.shortName].filter(Boolean).join(" ").toLocaleLowerCase("vi");return haystack.includes(query)};
